// Parse fix request
const input = $input.item.json.body || $input.item.json;

const params = {
  repo_url: input.repo_url,
  branch: input.branch || 'main',
  commit_sha: input.commit_sha,
  issues: typeof input.issues === 'string' ? JSON.parse(input.issues) : input.issues,
  work_dir: input.work_dir,
  create_pr: input.create_pr === true || input.create_pr === 'true',
  auto_merge: input.auto_merge === true,
  request_id: input.request_id || `fix-${Date.now()}`,
  fix_branch: `cortex/auto-fix-${Date.now()}`
};

// Extract repo info
const urlParts = params.repo_url?.split('/') || [];
params.repo_name = urlParts[urlParts.length - 1]?.replace('.git', '');
params.repo_owner = urlParts[urlParts.length - 2];

// Determine what can be auto-fixed
params.fixable = {
  lint: params.issues?.lint?.errors > 0 || params.issues?.lint?.warnings > 0,
  security: params.issues?.security?.high > 0 || params.issues?.security?.critical > 0
};

return [{
  json: {
    params: params,
    timestamp: new Date().toISOString()
  }
}];

// Set work directory
const params = $('Parse Request').item.json.params;
let workDir = params.work_dir;

if (!workDir || $('Has Work Dir?').item.json === false) {
  workDir = $input.item.json.stdout?.trim() || `/tmp/cortex-fix/${params.request_id}/repo`;
}

return [{
  json: {
    params: {...params, work_dir: workDir},
    work_dir: workDir
  }
}];

// Check if there are actual changes
const diffOutput = $input.item.json.stdout || '';
const hasChanges = diffOutput.trim().length > 0 && !diffOutput.includes('nothing to commit');

const context = $('Set Work Dir').item.json;

return [{
  json: {
    ...context,
    has_changes: hasChanges,
    diff_summary: diffOutput.trim()
  }
}];

// Prepare final result
const context = $('Evaluate Changes').item.json;
let prUrl = null;
let prNumber = null;

try {
  const prResponse = $('Create PR').item?.json;
  prUrl = prResponse?.html_url;
  prNumber = prResponse?.number;
} catch (e) { /* no PR created */ }

return [{
  json: {
    success: true,
    request_id: context.params.request_id,
    repo: context.params.repo_url,
    branch: context.params.branch,
    fix_branch: context.params.fix_branch,
    changes_applied: context.has_changes,
    diff_summary: context.diff_summary,
    pr_created: prUrl !== null,
    pr_url: prUrl,
    pr_number: prNumber,
    timestamp: new Date().toISOString()
  }
}];

// No changes result
const context = $('Evaluate Changes').item.json;

return [{
  json: {
    success: true,
    request_id: context.params.request_id,
    repo: context.params.repo_url,
    changes_applied: false,
    message: 'No fixable issues found or all issues require manual intervention',
    timestamp: new Date().toISOString()
  }
}];
